  const bySession = new Map()
  const list = []
  for (const workspace of workspaces?.items ?? []) {
    list.push(workspace)
    for (const sessionId of workspace.sessionIds ?? []) bySession.set(sessionId, workspace)
  }
  return { bySession, list }
